create table public.owner_profile_verification_tokens (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null, token_hash text not null unique, display_name text not null, designation text not null, organization text not null, status text not null default 'active', created_at timestamptz not null default now(), expires_at timestamptz not null, revoked_at timestamptz); alter table public.owner_profile_verification_tokens enable row level security; revoke all on public.owner_profile_verification_tokens from anon, authenticated;